css:
.loader { display: inline-flex; align-items: center; width: var(--loader-size); }
.loader span { width: calc(var(--loader-size) * .34); height: calc(var(--loader-size) * .34); border-radius: 9999px; background: var(--loader-color); box-shadow: 0 0 0 calc(var(--loader-size) * .03) color-mix(in srgb, var(--loader-color) 18%, transparent); animation: twAvatar calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader span:nth-child(2) { margin-left: calc(var(--loader-size) * -.12); background: var(--loader-secondary-color); animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(3) { margin-left: calc(var(--loader-size) * -.12); animation-delay: calc(var(--loader-speed) * .4); }
@keyframes twAvatar { 0%, 100% { transform: translateY(0) scale(.88); opacity: .5; } 50% { transform: translateY(-14%) scale(1); opacity: 1; } }
